function drawCurve(){const c=$('toneCurve');if(!c||!selected())return;const g=c.getContext('2d');g.fillStyle='#f8fafc';g.fillRect(0,0,256,256);g.strokeStyle='#d8dfe7';g.lineWidth=1;for(let i=0;i<=4;i++){g.beginPath();g.moveTo(i*64,0);g.lineTo(i*64,256);g.moveTo(0,i*64);g.lineTo(256,i*64);g.stroke()}g.strokeStyle='#ff5a0a';g.lineWidth=2;g.beginPath();toneTable(selected().adjust.curve).forEach((v,x)=>{if(!x)g.moveTo(x,255-v);else g.lineTo(x,255-v)});g.stroke();selected().adjust.curve.forEach((v,i)=>{g.beginPath();g.arc([3,64,128,192,252][i],clamp(255-v,3,252),5,0,Math.PI*2);g.fillStyle='#ff5a0a';g.fill()})}
