function dispatch(cmd){
    if(busy)return;const l=selected();
    if(advanced?.command(cmd))return;
    if(cmd==='insert'||cmd==='merge'){extraAction=cmd;$('imageAdditional').click();return}
    if(cmd==='background'){removeBackground();return}
    if(cmd==='clone-source'){healMode='clone';pickClone=true;message('Seleção de origem ativada. Clique em uma área limpa da imagem.');$('imageHint').textContent='Clique em uma área limpa da imagem para definir a origem do carimbo.';renderControls();drawOverlay();return}
    if(cmd==='reset-crop'){crop={x:0,y:0,w:state.width,h:state.height};syncCropFields();drawOverlay();return}
    if(cmd==='apply-crop'){clampCrop();checkpoint();const c={x:Math.round(crop.x),y:Math.round(crop.y),w:Math.round(crop.w),h:Math.round(crop.h)};state.layers.forEach(layer=>{layer.x-=c.x;layer.y-=c.y});state.width=c.w;state.height=c.h;crop={x:0,y:0,w:c.w,h:c.h};changed(true);message('Corte aplicado. Use Desfazer para recuperar o enquadramento anterior.');return}
    if(cmd==='delete'&&state.layers.length===1){message('Mantenha pelo menos uma camada.',true);return}
    if(cmd==='delete'&&l.isBase){message('A imagem original é protegida. Selecione uma camada adicionada para excluí-la.',true);return}
    if(cmd==='duplicate'&&state.layers.length>=8){message('O limite é de 8 camadas.',true);return}
    checkpoint();
    if(cmd==='rotate-left'||cmd==='rotate-right'){const oldW=state.width,oldH=state.height,right=cmd==='rotate-right';state.layers.forEach(layer=>{const cx=layer.x+layer.w/2,cy=layer.y+layer.h/2;layer.x=(right?oldH-cy:cy)-layer.w/2;layer.y=(right?cx:oldW-cx)-layer.h/2;layer.angle=((layer.angle+(right?90:-90)+540)%360)-180});state.width=oldH;state.height=oldW;crop=null}
    if(cmd==='flip-x')l.flipX=!l.flipX;if(cmd==='flip-y')l.flipY=!l.flipY;
    if(cmd==='reset-adjust')l.adjust=defaults();
    if(cmd==='reset-mask'){l.mask=makeCanvas(l.source.width,l.source.height);l.mask.getContext('2d').fillStyle='#fff';l.mask.getContext('2d').fillRect(0,0,l.mask.width,l.mask.height)}
    if(cmd==='invert-mask'){l.mask=copyCanvas(l.mask);const c=l.mask.getContext('2d'),d=c.getImageData(0,0,l.mask.width,l.mask.height);for(let i=3;i<d.data.length;i+=4)d.data[i]=255-d.data[i];c.putImageData(d,0,0)}
    if(cmd==='duplicate'){const copy={...l,id:uid(),name:l.name+' (cópia)',isBase:false,adjust:{...l.adjust,curve:[...l.adjust.curve]},cache:null};state.layers.push(copy);state.selected=copy.id}
    if(cmd==='delete'){state.layers=state.layers.filter(x=>x.id!==l.id);state.selected=state.layers.at(-1).id}
    if(cmd==='up'||cmd==='down'){const i=state.layers.indexOf(l),j=clamp(i+(cmd==='up'?1:-1),0,state.layers.length-1);[state.layers[i],state.layers[j]]=[state.layers[j],state.layers[i]]}
    changed(true);
}
$('imageAdditional').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const direction=$('mergeDirection')?.value||'right',gap=Number(controls.querySelector('[data-number="gap"]')?.value)||0;await activity('Adicionando imagem...',async()=>{if(state.layers.length>=8)throw new Error('O limite é de 8 camadas.');const {source}=await decode(file);const pixels=state.layers.reduce((s,l)=>s+l.source.width*l.source.height,0)+source.width*source.height;if(pixels>16000000)throw new Error('As camadas excedem 16 megapixels. Use imagens menores.');const layer=newLayer(source,file.name);let layout;
    if(extraAction==='merge'){const scale=['left','right'].includes(direction)?state.height/source.height:state.width/source.width;layer.w=Math.round(source.width*scale);layer.h=Math.round(source.height*scale);layout=mergedLayout(state.width,state.height,layer.w,layer.h,direction,gap);if(layout.width>6000||layout.height>6000||layout.width*layout.height>16000000)throw new Error('A mesclagem ultrapassa 6000 px ou 16 megapixels. Recorte a tela antes de mesclar novamente.')}
    checkpoint();if(layout){state.layers.forEach(l=>{l.x+=layout.shiftX;l.y+=layout.shiftY});layer.x=layout.x;layer.y=layout.y;state.width=layout.width;state.height=layout.height}else{const scale=Math.min(1,state.width*.65/source.width,state.height*.65/source.height);layer.w=source.width*scale;layer.h=source.height*scale;layer.x=(state.width-layer.w)/2;layer.y=(state.height-layer.h)/2}state.layers.push(layer);state.selected=layer.id;crop=null;mode='layers';setMode(mode);changed(true);message('Imagem adicionada como camada independente.')})};

$('imageUndo').onclick=()=>{if(busy||!history.length)return;future.push(snapshot());state=history.pop();crop=null;cloneSource=null;sliderEdit=false;if(mode==='crop')crop={x:0,y:0,w:state.width,h:state.height};changed(true)};
$('imageRedo').onclick=()=>{if(busy||!future.length)return;history.push(snapshot());state=future.pop();crop=null;cloneSource=null;if(mode==='crop')crop={x:0,y:0,w:state.width,h:state.height};changed(true)};
function clampCrop(){crop.x=clamp(crop.x,0,state.width-1);crop.y=clamp(crop.y,0,state.height-1);crop.w=clamp(crop.w,1,state.width-crop.x);crop.h=clamp(crop.h,1,state.height-crop.y)}
function syncCropFields(){for(const key of ['x','y','w','h']){const input=controls.querySelector(`[data-number="crop-${key}"]`);if(input)input.value=Math.round(crop[key])}}
function isPainting(){return mode==='background'||(mode==='layers'&&paintLayers)}
function brushDot(context,x,y,r,operation='source-over',color='255,255,255'){
    context.save();context.globalCompositeOperation=operation;context.globalAlpha=brushStrength/100;context.fillStyle=`rgb(${color})`;
    if(maskTip==='round'){const g=context.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgb(${color})`);g.addColorStop(.65,`rgb(${color})`);g.addColorStop(1,`rgba(${color},0)`);context.fillStyle=g;context.fillRect(x-r,y-r,r*2,r*2)}
    else if(maskTip==='square')context.fillRect(x-r,y-r,r*2,r*2);
    else if(maskTip==='rectangle')context.fillRect(x-r,y-r*.55,r*2,r*1.1);
    else if(maskTip==='letter'){context.font=`bold ${r*2}px Arial`;context.textAlign='center';context.textBaseline='middle';context.fillText(maskLetter||'A',x,y)}
    else{const count=Math.max(8,Math.round(r*(maskTip==='spray'?2.5:1.4)));for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,distance=Math.sqrt(Math.random())*r,size=maskTip==='chalk'?Math.max(1,r*.11):Math.max(1,r*.055);context.fillRect(x+Math.cos(angle)*distance-size/2,y+Math.sin(angle)*distance-size/2,size,size)}}
    context.restore();
}
function paintBetween(a,b,callback){const length=Math.hypot(b.x-a.x,b.y-a.y),steps=Math.max(1,Math.ceil(length/Math.max(1,brush/5)));for(let i=0;i<=steps;i++){const t=i/steps;callback(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t)}}
overlay.onpointerdown=e=>{
    if(busy||e.button!==0||!state.layers.length)return;e.preventDefault();overlay.focus();overlay.setPointerCapture(e.pointerId);const p=point(e),l=selected();
    if(l.locked&&['move','layers','insert','rotate','merge','background','heal','clone','brush','pencil','eraser','bucket','gradient','blur','sharpen','smudge','text','text-vertical','pen','rectangle','ellipse','polygon'].includes(mode)){message('Esta camada está bloqueada. Desbloqueie-a no painel Camadas para editar.',true);return}
    if(advanced?.pointerDown(e,p))return;
    if(mode==='crop'){const handle=cropHandles().find(([,x,y])=>Math.hypot(p.x-x,p.y-y)<12*screenScale());drag={kind:'crop',handle:handle?.[0]||((p.x>=crop.x&&p.x<=crop.x+crop.w&&p.y>=crop.y&&p.y<=crop.y+crop.h)?'move':'new'),start:p,original:{...crop}};return}
    if(mode==='heal'||mode==='clone'||isPainting()){const lp=toLayerPoint(l,p);if(lp.x<0||lp.y<0||lp.x>l.source.width||lp.y>l.source.height)return;
        if((mode==='heal'||mode==='clone')&&(e.altKey||pickClone)){cloneSource=lp;pickClone=false;healMode='clone';message('Origem do carimbo escolhida. Agora pinte sobre o objeto.');renderControls();drawOverlay();return}
        if((mode==='heal'||mode==='clone')&&healMode==='clone'&&!cloneSource){message('Escolha a origem com Alt+clique ou com o botão Escolher origem.',true);return}
        if(!isPainting()&&advanced&&!advanced.canRasterize(l))return;
        checkpoint();if(isPainting()){const original=l.mask;l.mask=copyCanvas(l.mask);drag={kind:'mask',last:lp,original};paintMask(lp)}else if(healMode==='clone'){l.vector=null;cloneOffset={x:cloneSource.x-lp.x,y:cloneSource.y-lp.y};const original=l.source;l.source=copyCanvas(l.source);drag={kind:'clone',last:lp,original};paintClone(lp)}else{l.vector=null;stroke=makeCanvas(l.source.width,l.source.height);drag={kind:'heal',last:lp};paintHeal(lp)}return;
    }
    if(!['move','layers','insert','rotate','merge'].includes(mode))return;
    const hit=[...state.layers].reverse().find(layer=>{if(!layer.visible)return false;const q=toLayerPoint(layer,p);return q.x>=0&&q.y>=0&&q.x<=layer.source.width&&q.y<=layer.source.height});
    if(hit){state.selected=hit.id;renderLayerList();renderControls();const q=toLayerPoint(hit,p);checkpoint();drag={kind:Math.hypot((q.x-hit.source.width)*hit.w/hit.source.width,(q.y-hit.source.height)*hit.h/hit.source.height)<18*screenScale()?'resize':'move',start:p,original:{x:hit.x,y:hit.y,w:hit.w,h:hit.h}};drawOverlay()}
};
function paintMask(p){const l=selected();paintBetween(drag.last,p,(x,y)=>brushDot(l.mask.getContext('2d'),x,y,brush/2,maskMode==='erase'?'destination-out':'source-over'));if(advanced)l.mask=advanced.restrictStroke(l,l.mask,drag.original);drag.last=p;l.pixelVersion=(l.pixelVersion||0)+1;l.cache=null;changed()}
function paintHeal(p){paintBetween(drag.last,p,(x,y)=>{const c=stroke.getContext('2d');c.fillStyle='#ff4938';c.beginPath();c.arc(x,y,brush/2,0,Math.PI*2);c.fill()});drag.last=p;drawOverlay()}
function paintClone(p){
    const l=selected(),r=brush/2,stamp=makeCanvas(brush,brush);
    paintBetween(drag.last,p,(x,y)=>{const c=stamp.getContext('2d');c.clearRect(0,0,stamp.width,stamp.height);c.drawImage(drag.original,x+cloneOffset.x-r,y+cloneOffset.y-r,brush,brush,0,0,brush,brush);c.globalCompositeOperation='destination-in';const g=c.createRadialGradient(r,r,0,r,r,r);g.addColorStop(.6,`rgba(255,255,255,${brushStrength/100})`);g.addColorStop(1,'rgba(255,255,255,0)');c.fillStyle=g;c.fillRect(0,0,brush,brush);c.globalCompositeOperation='source-over';l.source.getContext('2d').drawImage(stamp,x-r,y-r)});
    if(advanced)l.source=advanced.restrictStroke(l,l.source,drag.original);
    drag.last=p;l.pixelVersion=(l.pixelVersion||0)+1;l.cache=null;invalidateResult();previewRasterLayer(l,l.source);drawOverlay();
}
overlay.onpointermove=e=>{if(busy)return;const p=point(e);hoverPoint=p;if($('imagePointerInfo'))$('imagePointerInfo').textContent=`X ${Math.round(p.x)}  Y ${Math.round(p.y)}`;if(!drag)drawOverlay();if(advanced?.pointerMove(e,p))return;if(!drag)return;const l=selected();
    if(drag.kind==='crop'){const o=drag.original,dx=p.x-drag.start.x,dy=p.y-drag.start.y,h=drag.handle;if(h==='move'){crop.x=clamp(o.x+dx,0,state.width-o.w);crop.y=clamp(o.y+dy,0,state.height-o.h)}else if(h==='new'){crop={x:Math.min(p.x,drag.start.x),y:Math.min(p.y,drag.start.y),w:Math.abs(dx),h:Math.abs(dy)}}else{let x1=o.x,y1=o.y,x2=o.x+o.w,y2=o.y+o.h;if(h.includes('w'))x1=clamp(o.x+dx,0,x2-1);if(h.includes('e'))x2=clamp(o.x+o.w+dx,x1+1,state.width);if(h.includes('n'))y1=clamp(o.y+dy,0,y2-1);if(h.includes('s'))y2=clamp(o.y+o.h+dy,y1+1,state.height);crop={x:x1,y:y1,w:x2-x1,h:y2-y1}}if(h!=='move'&&cropRatio!=='free'){const ratio=Number(cropRatio);crop.h=crop.w/ratio;if(crop.h>state.height-crop.y){crop.h=state.height-crop.y;crop.w=crop.h*ratio}}clampCrop();syncCropFields();drawOverlay();return}
    if(['mask','heal','clone'].includes(drag.kind)){const lp=toLayerPoint(l,p);if(drag.kind==='mask')paintMask(lp);if(drag.kind==='heal')paintHeal(lp);if(drag.kind==='clone')paintClone(lp);return}
    const o=drag.original;if(drag.kind==='move'){l.x=clamp(o.x+p.x-drag.start.x,-l.w+1,state.width-1);l.y=clamp(o.y+p.y-drag.start.y,-l.h+1,state.height-1)}else{const factor=clamp(1+(p.x-drag.start.x)/o.w,.05,5);l.w=o.w*factor;l.h=o.h*factor}changed();drawOverlay();
};
async function endPointer(){
    if(!drag)return;const action=drag.kind;drag=null;
    if(action==='heal'&&stroke){
        const l=selected(),m=stroke.getContext('2d').getImageData(0,0,stroke.width,stroke.height).data,mask=new Uint8Array(m.length/4);for(let i=0;i<mask.length;i++)mask[i]=m[i*4+3];stroke=null;
        await activity('Corrigindo a área selecionada...',async()=>{const original=l.source,d=original.getContext('2d').getImageData(0,0,original.width,original.height),pixels=await pixelsJob('heal',d.data,original.width,original.height,{padding:2},mask);l.source=copyCanvas(original);l.source.getContext('2d').putImageData(new ImageData(pixels,l.source.width,l.source.height),0,0);if(advanced)l.source=advanced.restrictStroke(l,l.source,original);l.pixelVersion=(l.pixelVersion||0)+1;l.cache=null;l.thumb=thumbnail(l.source);changed();renderLayerList();message('Correção aplicada. Se restar algum detalhe, pinte novamente ou use o carimbo manual.')});
    }else if(action==='clone'){const l=selected();l.thumb=thumbnail(l.source);changed();renderLayerList();message('Carimbo aplicado. Continue pintando para copiar a mesma origem ou escolha outra área.');drawOverlay()}
    else if(action==='move'||action==='resize')renderControls();drawOverlay();
}
overlay.onpointerup=async e=>{if(await advanced?.pointerUp(e))return;await endPointer()};overlay.onpointercancel=async e=>{if(advanced?.cancelPointer())return;await endPointer()};
overlay.onpointerleave=()=>{hoverPoint=null;if($('imagePointerInfo'))$('imagePointerInfo').textContent='Pronto';drawOverlay()};

async function removeBackground(){await activity('Tirando o fundo com IA local. Aguarde...',async()=>{const l=selected(),small=makeCanvas(320,320),s=small.getContext('2d');s.fillStyle='#fff';s.fillRect(0,0,320,320);s.drawImage(l.source,0,0,320,320);const input=normalizeModelInput(s.getImageData(0,0,320,320).data);if(!aiWorker)aiWorker=new Worker(new URL('./background-worker.js',import.meta.url));
    const mask=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{aiWorker.terminate();aiWorker=null;reject(new Error('A remoção automática excedeu o tempo. Tente uma imagem menor ou refine pela máscara.'))},120000);aiWorker.onmessage=({data})=>{clearTimeout(timer);data.error?reject(new Error('Não foi possível remover o fundo: '+data.error)):resolve(data.mask)};aiWorker.onerror=()=>{clearTimeout(timer);aiWorker.terminate();aiWorker=null;reject(new Error('Falha ao carregar a IA local. Confira os arquivos de modelo em assets/vendor/image-ai.'))};aiWorker.postMessage({input},[input.buffer])});
    const d=s.createImageData(320,320);for(let i=0;i<mask.length;i++){d.data[i*4]=255;d.data[i*4+1]=255;d.data[i*4+2]=255;d.data[i*4+3]=mask[i]}s.putImageData(d,0,0);checkpoint();l.mask=makeCanvas(l.source.width,l.source.height);const m=l.mask.getContext('2d');m.imageSmoothingEnabled=true;m.imageSmoothingQuality='high';m.drawImage(small,0,0,l.mask.width,l.mask.height);changed();await renderScene();message('Fundo removido. Use o pincel para refinar e finalize em PNG para manter a transparência.')})}

$('imageFinalize').onclick=()=>activity(stickerMode?'Criando a figurinha...':'Finalizando a imagem...',async()=>{
    await renderScene();if(renderAgain)await renderScene();
    const format=stickerMode?'webp':$('imageFormat').value,quality=Number($('imageQuality').value)/100;
    let output=makeCanvas(state.width,state.height),c=output.getContext('2d');
    if(['jpeg','jpg','pdf'].includes(format)){c.fillStyle='#fff';c.fillRect(0,0,output.width,output.height)}c.drawImage(canvas,0,0);
    let encoded;if(stickerMode){const sticker=await encodeSticker(output,$('imageBackground').value,$('imageBackgroundColor').value,quality);output=sticker.canvas;encoded=sticker}else encoded=await encodeCanvas(output,format,quality);
    invalidateResult();outputBlob=encoded.blob;outputCanvas=output;outputUrl=URL.createObjectURL(outputBlob);
    $('imageDownload').href=outputUrl;$('imageDownload').download=stickerMode?`${fileName}_figurinha.webp`:`${fileName}_editada.${encoded.extension}`;
    $('imageResultPreview').src=format==='pdf'?output.toDataURL('image/png'):outputUrl;$('imageResultInfo').textContent=`${output.width} × ${output.height} px • ${(outputBlob.size/1024).toFixed(1)} KB • ${encoded.extension.toUpperCase()}${stickerMode&&outputBlob.size<=100*1024?' • dentro do limite recomendado':''}`;
    $('imageResult').hidden=false;message(stickerMode?'Figurinha criada. Use Copiar imagem ou Baixar figurinha.':'Imagem finalizada. O download está pronto.');$('imageResult').scrollIntoView({behavior:'smooth',block:'center'});
});
